-- v1.11: rules reference with search, general rules from warhammer-oracle, reference update journal,
-- Sweep & Clear Tac Op. Append-only: existing tables and columns are not changed.
-- db/migrate.sh grants the runtime role read-only access to the new reference tables.

-- 1. Sweep & Clear (Seek & Destroy): checked against the official GW "Approved Ops: Update Log" (Errata August '26)
--    and the current Wahapedia card; now verified and active (generated by tools/catalog-import from db/seed.json).
--    Played matches keep their frozen rules_snapshot.
INSERT INTO catalogs(code,kind,edition,label,label_en,config,active,source,source_url,retrieved_at,rules_version,content_hash,verification)
SELECT x->>'code',x->>'kind',x->>'edition',x->>'label',coalesce(x->>'label_en',''),x->'config',(x->>'active')::boolean,
x->>'source',x->>'source_url',(x->>'retrieved_at')::timestamptz,x->>'rules_version',x->>'content_hash',x->>'verification'
FROM jsonb_array_elements('[{"active":true,"code":"2024-wahapedia-tac-op-sweep-clear","config":{"archetype":"Seek & Destroy","errata":"GW Approved Ops: Update Log, Errata August ’26","max_per_battle":6,"pack":"approved2025","per_turn_caps":[0,2,2,2],"reveal":"Первое выведение из строя врага, оспаривающего маркер цели, либо первое действие Clear своим оперативником (что раньше).","summary":"Когда выводится из строя враг, оспаривающий маркер цели, этот маркер становится swept до шага Ready следующей фазы стратегии (по разъяснению GW выведение оперативника с правилом Expendable маркер swept не делает). Действие Clear (1AP): маркер, который контролирует активный оперативник, расчищен до конца поворота; нельзя в первом повороте и в пределах контроля врага. В конце каждого поворота после первого: центральный или вражеский маркер расчищен и враг его не оспаривает — 1 VP, а если он ещё и swept — 2 VP. Если свои оперативники контролируют swept-маркер — 1 VP. Максимум 2 VP за поворот."},"content_hash":"c3617644be41bbdb8ae9311512b373d27fea142906e6d7acef63786bfb070e44","edition":"2024","kind":"tac_op","label":"Зачистка","label_en":"Sweep & Clear","retrieved_at":"2026-11-04T08:13:59.769275+00:00","rules_version":"Approved Ops 2025 — August 2026","source":"wahapedia","source_url":"https://wahapedia.ru/kill-team3/the-rules/approved-ops-2025/","verification":"verified"}]'::jsonb) x
ON CONFLICT(code) DO UPDATE SET label=excluded.label,label_en=excluded.label_en,config=excluded.config,active=excluded.active,
source=excluded.source,source_url=excluded.source_url,retrieved_at=excluded.retrieved_at,rules_version=excluded.rules_version,content_hash=excluded.content_hash,verification=excluded.verification;

-- 2. Search helpers. Case and «ё» folding does not depend on the database locale: lower() covers ASCII
--    (and Cyrillic in UTF-8 locales), translate() covers Cyrillic in the C locale too; runs of white space become
--    one space (the same folding as api/library.fold).
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE FUNCTION ks_fold(t text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS
$$ SELECT btrim(regexp_replace(translate(lower(coalesce(t, '')), 'ЁАБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯё', 'еабвгдежзийклмнопрстуфхцчшщъыьэюяе'),
                               '\s+', ' ', 'g')) $$;
CREATE FUNCTION ks_arr(j jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE PARALLEL SAFE AS
$$ SELECT CASE WHEN jsonb_typeof(j) = 'array' THEN j ELSE '[]'::jsonb END $$;
-- Rule text of a team data block list ({k, t}); lore is left out of the search.
CREATE FUNCTION ks_blocks(body jsonb) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS
$$ SELECT coalesce(string_agg(b->>'t', E'\n' ORDER BY n), '') FROM jsonb_array_elements(ks_arr(body)) WITH ORDINALITY x(b, n)
   WHERE jsonb_typeof(b) = 'object' AND coalesce(b->>'k', 'p') <> 'lore' $$;

-- 3. General rules imported by the operator (scripts/import-rules.sh, scripts/update-reference.sh) from
--    warhammer-oracle: weapon rules (BSData "2024 - Kill Team.gst" shared rules) and the phase overview written by
--    the oracle authors (verification 'unverified'). Not shipped with the release.
CREATE TABLE rule_entries (
 code text PRIMARY KEY CHECK(code ~ '^(weapon|phase)-[a-z0-9-]{1,60}$'),
 kind text NOT NULL CHECK(kind IN ('weapon_rule','phase')),
 name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),
 name_ru text NOT NULL DEFAULT '',
 text_en text NOT NULL,
 text_ru text NOT NULL DEFAULT '', -- editorial Russian paraphrase (api/data/weapon-rules-ru.json), not GW text
 aliases text[] NOT NULL DEFAULT '{}', -- other Russian names in use (same file), for the search only
 details jsonb NOT NULL DEFAULT '{}', -- phase: order, steps, tips
 verification text NOT NULL CHECK(verification IN ('bsdata','unverified')),
 source jsonb NOT NULL, -- repo, tag, commit, path, sha256, generated_at, upstream
 sort int NOT NULL DEFAULT 0,
 active boolean NOT NULL DEFAULT true,
 content_hash text NOT NULL CHECK(content_hash ~ '^[0-9a-f]{64}$'),
 imported_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE rule_imports (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 imported_at timestamptz NOT NULL DEFAULT now(),
 built_at timestamptz,
 sources jsonb NOT NULL,
 rules int NOT NULL CHECK(rules >= 0),
 phases int NOT NULL CHECK(phases >= 0),
 warnings jsonb NOT NULL DEFAULT '[]'
);
-- Journal of scripts/update-reference.sh (manual run or systemd timer), shown in #admin.
CREATE TABLE reference_updates (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 started_at timestamptz NOT NULL,
 finished_at timestamptz NOT NULL DEFAULT now(),
 action text NOT NULL CHECK(action IN ('update','rollback')),
 status text NOT NULL CHECK(status IN ('ok','unchanged','failed')),
 trigger text NOT NULL CHECK(trigger IN ('manual','timer')),
 backup text NOT NULL DEFAULT '', -- pg_dump file made by scripts/backup.sh before loading
 snapshot text NOT NULL DEFAULT '', -- directory with the previous and the loaded bundles (for --rollback)
 sources jsonb NOT NULL DEFAULT '{}',
 report jsonb NOT NULL DEFAULT '{}'
);
CREATE INDEX reference_updates_recent ON reference_updates(finished_at DESC);

-- 4. One search index over the whole reference: general rules, KILLSTASS catalog (missions, Tac Ops, rule
--    summaries) and game sequence, imported teams with operatives, faction rules, ploys and equipment.
--    Refreshed by the owner after every import (api/teamdata.py, api/rulesdata.py, tools/catalog-import).
CREATE MATERIALIZED VIEW reference_search AS
WITH docs AS (
 SELECT 'rule:' || r.code AS id, r.kind, r.name AS title, nullif(r.name_ru, '') AS subtitle,
        NULL::text AS team_slug, NULL::text AS team_name, NULL::text AS team_label, NULL::text AS tab, NULL::text AS anchor,
        r.code, r.text_en AS body, r.text_ru AS body_ru, r.verification,
        'https://github.com/' || (r.source->>'repo') || '/blob/' || (r.source->>'commit') || '/' || (r.source->>'path') AS source_url,
        CASE r.kind WHEN 'weapon_rule' THEN 1 ELSE 6 END AS rank, r.sort, nullif(array_to_string(r.aliases, ', '), '') AS alias
 FROM rule_entries r WHERE r.active
 UNION ALL
 SELECT 'cat:' || c.code, c.kind, c.label, nullif(c.label_en, ''), NULL, NULL, NULL, NULL, NULL, c.code,
        concat_ws(E'\n', c.config->>'archetype', c.config->>'reveal', c.config->>'summary'), '', c.verification, c.source_url, 2, c.id::int, NULL
 FROM catalogs c WHERE c.active AND c.verification = 'verified' AND c.edition = '2024' AND c.kind IN ('mission','tac_op','rule')
 UNION ALL
 SELECT 'seq:' || s.code, 'sequence', s.label, s.phase, NULL, NULL, NULL, NULL, NULL, s.code, s.description, '', s.verification,
        s.source_url, 3, s.phase_order * 100 + s.step_order, NULL
 FROM game_sequence s WHERE s.active AND s.verification = 'verified' AND s.edition = '2024'
 UNION ALL
 SELECT 'team:' || t.slug, 'team', t.name, (SELECT string_agg(a, ', ') FROM jsonb_array_elements_text(ks_arr(t.data->'archetypes')) a),
        t.slug, t.name, c.label, 'operatives', NULL, c.code,
        (SELECT string_agg(f->>'name', E'\n') FROM jsonb_array_elements(ks_arr(t.data->'faction_rules')) f), '', 'import', NULL, 3, 0, NULL
 FROM team_data t LEFT JOIN catalogs c ON c.id = t.catalog_id WHERE t.active
 UNION ALL
 SELECT 'op:' || t.slug || ':' || (o.n - 1), 'operative', o.v->>'name',
        (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(ks_arr(o.v->'keywords')) k),
        t.slug, t.name, c.label, 'operatives', 'op-' || (o.n - 1), NULL,
        concat_ws(E'\n',
          (SELECT string_agg(concat_ws(' ', w->>'name', w->>'wr'), E'\n') FROM jsonb_array_elements(ks_arr(o.v->'weapons')) w),
          (SELECT string_agg(concat_ws(': ', a->>'name', a->>'text'), E'\n') FROM jsonb_array_elements(ks_arr(o.v->'abilities')) a),
          (SELECT string_agg(concat_ws(': ', a->>'name', a->>'text'), E'\n') FROM jsonb_array_elements(ks_arr(o.v->'actions')) a)),
        '', 'import', NULL, 4, o.n::int, NULL
 FROM team_data t LEFT JOIN catalogs c ON c.id = t.catalog_id CROSS JOIN LATERAL jsonb_array_elements(ks_arr(t.data->'operatives')) WITH ORDINALITY o(v, n)
 WHERE t.active AND jsonb_typeof(o.v) = 'object'
 UNION ALL
 SELECT sec.prefix || ':' || t.slug || ':' || (x.n - 1), sec.kind, x.v->>'name', NULL, t.slug, t.name, c.label, sec.tab, sec.prefix || '-' || (x.n - 1), NULL,
        concat_ws(E'\n', ks_blocks(x.v->'body'),
          (SELECT string_agg(concat_ws(E'\n', p->>'name', ks_blocks(p->'body')), E'\n') FROM jsonb_array_elements(ks_arr(x.v->'options')) p)),
        '', 'import', NULL, sec.rank, x.n::int, NULL
 FROM team_data t LEFT JOIN catalogs c ON c.id = t.catalog_id
 CROSS JOIN (VALUES ('fr', 'faction_rule', 'rules', 'faction_rules', 4), ('sp', 'ploy', 'ploys', 'strategy_ploys', 4),
                    ('fp', 'ploy', 'ploys', 'firefight_ploys', 4), ('eq', 'equipment', 'equipment', 'equipment', 5)) sec(prefix, kind, tab, field, rank)
 CROSS JOIN LATERAL jsonb_array_elements(ks_arr(t.data->sec.field)) WITH ORDINALITY x(v, n)
 WHERE t.active AND jsonb_typeof(x.v) = 'object' AND coalesce(x.v->>'name', '') <> ''
)
SELECT d.*, ks_fold(d.title) AS title_f, ks_fold(d.subtitle) AS sub_f, ks_fold(d.alias) AS alias_f,
       ks_fold(concat_ws(E'\n', d.title, d.subtitle, d.alias, d.body, d.body_ru)) AS text_f,
       setweight(to_tsvector('russian', ks_fold(concat_ws(' ', d.title, d.subtitle, d.alias))), 'A')
       || setweight(to_tsvector('russian', ks_fold(concat_ws(E'\n', d.body, d.body_ru))), 'C') AS doc
FROM docs d WHERE coalesce(d.title, '') <> '';
CREATE UNIQUE INDEX reference_search_id ON reference_search(id);
CREATE INDEX reference_search_doc ON reference_search USING gin(doc);
CREATE INDEX reference_search_title ON reference_search USING gin(title_f gin_trgm_ops);
CREATE INDEX reference_search_text ON reference_search USING gin(text_f gin_trgm_ops);
